<?php
require_once __DIR__ . '/config/koneksi.php';
$errors=[];
$types=['Organik','Anorganik','Sampah B3 rumah tangga','Sampah elektronik','Sampah besar','Limbah cair','Lainnya'];
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf();$title=trim((string)($_POST['judul_laporan']??''));$type=(string)($_POST['jenis_sampah']??'');$description=trim((string)($_POST['deskripsi']??''));$location=trim((string)($_POST['lokasi']??''));
 if($title===''||mb_strlen($title)>180)$errors[]='Judul wajib diisi (maksimal 180 karakter).';
 if(!in_array($type,$types,true))$errors[]='Pilih jenis sampah yang tersedia.';
 if($description===''||mb_strlen($description)>5000)$errors[]='Deskripsi wajib diisi (maksimal 5.000 karakter).';
 if($location===''||mb_strlen($location)>220)$errors[]='Lokasi wajib diisi (maksimal 220 karakter).';
 if(empty($_SESSION['last_public_report'])||time()-$_SESSION['last_public_report']>20){
    if(!$errors){try{$filename=null;$file=$_FILES['foto']??[];if(($file['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_NO_FILE){if(($file['error']??UPLOAD_ERR_OK)!==UPLOAD_ERR_OK||($file['size']??0)>5*1024*1024)throw new RuntimeException('Ukuran foto maksimal 5 MB.');$mime=(new finfo(FILEINFO_MIME_TYPE))->file($file['tmp_name']);$extensions=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'];if(!isset($extensions[$mime]))throw new RuntimeException('Foto harus berformat JPG, PNG, atau WebP.');$filename=bin2hex(random_bytes(16)).'.'.$extensions[$mime];$directory=__DIR__.'/uploads/laporan_sampah';if(!is_dir($directory))mkdir($directory,0750,true);if(!move_uploaded_file($file['tmp_name'],$directory.'/'.$filename))throw new RuntimeException('Foto gagal disimpan.');}$code=bin2hex(random_bytes(16));$statement=$pdo->prepare('INSERT INTO laporan_sampah (judul_laporan,jenis_sampah,deskripsi,lokasi,tanggal_laporan,foto,kode_pelacakan_hash) VALUES (?,?,?,?,CURRENT_DATE,?,?)');$statement->execute([$title,$type,$description,$location,$filename,hash('sha256',$code)]);$_SESSION['last_public_report']=time();redirect('status_laporan.php?kode='.$code);}catch(Throwable $exception){error_log($exception->getMessage());$errors[]=$exception instanceof RuntimeException?$exception->getMessage():'Laporan belum dapat disimpan. Silakan coba kembali.';}}
 }else{$errors[]='Mohon tunggu sebentar sebelum mengirim laporan berikutnya.';}
}
?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Kirim Laporan Sampah</title><link href="https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Manrope:wght@400;500;600;700;800&display=swap" rel="stylesheet"><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.2/css/all.min.css" rel="stylesheet"><link href="<?=e(base_url('assets/css/style.css'))?>" rel="stylesheet"><link href="<?=e(base_url('assets/css/admin.css'))?>" rel="stylesheet"></head><body><?php require __DIR__.'/includes/navbar.php';?><main class="detail-wrap public-form-wrap"><div class="container"><a class="back-link" href="<?=e(base_url())?>"><i class="fa-solid fa-arrow-left"></i> Kembali ke beranda</a><div class="module-heading"><div><span class="eyebrow eyebrow-dark">KONTRIBUSI WARGA</span><h1>Kirim laporan sampah</h1><p>Laporan Anda membantu pengurus menentukan tindak lanjut. Identitas tidak diminta pada formulir publik.</p></div></div><?php if(isset($_GET['berhasil'])):?><div class="alert alert-success">Terima kasih. Laporan Anda sudah diterima pengurus.</div><?php endif;?><?php foreach($errors as $error):?><div class="alert alert-danger"><?=e($error)?></div><?php endforeach;?><form class="module-form" method="post" enctype="multipart/form-data"><?=csrf_field()?><div class="form-grid"><div class="field-group"><label for="judul_laporan">Judul laporan *</label><input class="form-control" id="judul_laporan" name="judul_laporan" maxlength="180" required value="<?=e($_POST['judul_laporan']??'')?>"></div><div class="field-group"><label for="jenis_sampah">Jenis sampah *</label><select class="form-select" id="jenis_sampah" name="jenis_sampah" required><option value="">Pilih jenis</option><?php foreach($types as $type):?><option <?=($_POST['jenis_sampah']??'')===$type?'selected':''?> value="<?=e($type)?>"><?=e($type)?></option><?php endforeach;?></select></div><div class="field-group full"><label for="lokasi">Lokasi *</label><input class="form-control" id="lokasi" name="lokasi" maxlength="220" required value="<?=e($_POST['lokasi']??'')?>"></div><div class="field-group full"><label for="deskripsi">Deskripsi *</label><textarea class="form-control" id="deskripsi" name="deskripsi" maxlength="5000" required><?=e($_POST['deskripsi']??'')?></textarea></div><div class="field-group full"><label for="foto">Foto kondisi (opsional)</label><input class="form-control" type="file" id="foto" name="foto" accept="image/jpeg,image/png,image/webp"><div class="field-help">JPG, PNG, atau WebP, maksimal 5 MB.</div></div></div><div class="form-actions"><button class="btn btn-admin-primary" type="submit"><i class="fa-solid fa-paper-plane me-2"></i>Kirim laporan</button><a class="btn btn-admin-light" href="<?=e(base_url())?>">Batal</a></div></form></div></main><?php require __DIR__.'/includes/footer.php';?></body></html>